export type HotFileWriteOwnerStatus = "owned" | "reentrant" | "conflict";

export interface HotFileWriteOwnerClaim {
  readonly status: HotFileWriteOwnerStatus;
  readonly path: string;
  readonly owner: string;
  readonly token?: string;
  readonly holder?: string;
  readonly conflict?: boolean;
}

export interface HotFileWriteOwnerLease extends HotFileWriteOwnerClaim {
  readonly status: "owned" | "reentrant";
  readonly token: string;
  readonly depth: number;
}

export interface HotFileWriteOwnerConflict extends HotFileWriteOwnerClaim {
  readonly status: "conflict";
  readonly holder: string;
  readonly conflict: true;
}

export interface FileMutationQueueLike {
  enqueue?<T>(key: string, task: () => Promise<T> | T): Promise<T>;
  run?<T>(key: string, task: () => Promise<T> | T): Promise<T>;
}

export interface HotFileWriteOwnerOptions {
  /** The existing per-file mutation queue. No queue is created by this module. */
  readonly queue: FileMutationQueueLike;
  readonly timeoutMs?: number;
}

export interface HotFileWriteOwnerClaimOptions {
  readonly timeoutMs?: number;
}

interface OwnerState {
  owner: string;
  token: string;
  depth: number;
  expiresAt?: number;
}

let tokenSequence = 0;

function nextToken(path: string, owner: string): string {
  tokenSequence += 1;
  return `hot-file-owner:${encodeURIComponent(path)}:${encodeURIComponent(owner)}:${tokenSequence}`;
}

function expired(state: OwnerState, now: number): boolean {
  return state.expiresAt !== undefined && state.expiresAt <= now;
}

/**
 * A small ownership layer over the runtime's existing file mutation queue.
 * Claims are made synchronously, so a second owner cannot silently race the
 * first owner. Actual mutations are submitted to the injected queue.
 */
export class HotFileWriteOwnerRegistry {
  private readonly states = new Map<string, OwnerState>();
  private readonly queue: FileMutationQueueLike;
  private readonly defaultTimeoutMs?: number;

  public constructor(options: HotFileWriteOwnerOptions) {
    this.queue = options.queue;
    this.defaultTimeoutMs = options.timeoutMs;
  }

  public claim(
    path: string,
    owner: string,
    options: HotFileWriteOwnerClaimOptions = {},
  ): HotFileWriteOwnerLease | HotFileWriteOwnerConflict {
    const key = this.key(path);
    const now = Date.now();
    const current = this.states.get(key);

    if (current && !expired(current, now)) {
      if (current.owner === owner) {
        current.depth += 1;
        return {
          status: "reentrant",
          path,
          owner,
          token: current.token,
          depth: current.depth,
        };
      }
      return {
        status: "conflict",
        path,
        owner,
        holder: current.owner,
        conflict: true,
      };
    }

    const timeoutMs = options.timeoutMs ?? this.defaultTimeoutMs;
    const state: OwnerState = {
      owner,
      token: nextToken(path, owner),
      depth: 1,
      expiresAt: timeoutMs === undefined ? undefined : now + timeoutMs,
    };
    this.states.set(key, state);
    return {
      status: "owned",
      path,
      owner,
      token: state.token,
      depth: 1,
    };
  }

  /** Releases one matching lease. A stale or mismatched token is ignored. */
  public release(path: string, token: string): boolean {
    const key = this.key(path);
    const current = this.states.get(key);
    if (!current || current.token !== token) {
      return false;
    }
    current.depth -= 1;
    if (current.depth <= 0) {
      this.states.delete(key);
    }
    return true;
  }

  /** Rolls back the claim, regardless of re-entrant depth. */
  public rollback(path: string, token: string): boolean {
    const key = this.key(path);
    const current = this.states.get(key);
    if (!current || current.token !== token) {
      return false;
    }
    this.states.delete(key);
    return true;
  }

  public holder(path: string): string | undefined {
    const current = this.states.get(this.key(path));
    if (!current || expired(current, Date.now())) {
      if (current) {
        this.states.delete(this.key(path));
      }
      return undefined;
    }
    return current.owner;
  }

  public async withOwnership<T>(
    path: string,
    owner: string,
    operation: () => Promise<T> | T,
    options: HotFileWriteOwnerClaimOptions = {},
  ): Promise<T> {
    const claim = this.claim(path, owner, options);
    if (claim.status === "conflict") {
      throw new HotFileWriteOwnerConflictError(claim);
    }

    try {
      const task = () => operation();
      if (this.queue.enqueue) {
        return await this.queue.enqueue(this.key(path), task);
      }
      if (this.queue.run) {
        return await this.queue.run(this.key(path), task);
      }
      throw new TypeError("The existing file mutation queue must provide enqueue() or run().");
    } catch (error) {
      this.rollback(path, claim.token);
      throw error;
    } finally {
      // A successful operation releases its claim. Rollback above already
      // removed it when the operation failed.
      if (this.holder(path) === owner) {
        this.release(path, claim.token);
      }
    }
  }

  private key(path: string): string {
    return path;
  }
}

export class HotFileWriteOwnerConflictError extends Error {
  public readonly conflict: HotFileWriteOwnerConflict;

  public constructor(conflict: HotFileWriteOwnerConflict) {
    super(`File write ownership conflict for ${conflict.path}; holder is ${conflict.holder}`);
    this.name = "HotFileWriteOwnerConflictError";
    this.conflict = conflict;
  }
}

export function createHotFileWriteOwnerRegistry(
  options: HotFileWriteOwnerOptions,
): HotFileWriteOwnerRegistry {
  return new HotFileWriteOwnerRegistry(options);
}

export default HotFileWriteOwnerRegistry;

